package com.blackwood.mystery.service;

import com.blackwood.mystery.dto.ApiDtos.*;
import com.blackwood.mystery.exception.GameException;
import com.blackwood.mystery.model.*;
import com.blackwood.mystery.repository.*;
import org.springframework.http.HttpStatus;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.util.stream.Collectors;

@Service
public class GameService {
 private final UserRepository users; private final TokenRepository tokens; private final GameSessionRepository sessions; private final CollectedClueRepository collected; private final LeaderboardRepository leaderboard; private final BCryptPasswordEncoder encoder; private final ScoringService scoring;
 public GameService(UserRepository u,TokenRepository t,GameSessionRepository s,CollectedClueRepository c,LeaderboardRepository l,BCryptPasswordEncoder e,ScoringService scoring){users=u;tokens=t;sessions=s;collected=c;leaderboard=l;encoder=e;this.scoring=scoring;}
 @Transactional public AuthResponse register(Credentials c){if(users.findByUsername(c.username()).isPresent())throw new GameException(HttpStatus.CONFLICT,"Username is already registered.");users.save(new AppUser(c.username(),encoder.encode(c.password())));return login(c);}
 @Transactional public AuthResponse login(Credentials c){AppUser u=users.findByUsername(c.username()).filter(x->encoder.matches(c.password(),x.getPasswordHash())).orElseThrow(()->new GameException(HttpStatus.UNAUTHORIZED,"Username or password is incorrect."));String token=UUID.randomUUID().toString();tokens.save(new TokenEntity(token,u));return new AuthResponse(token,u.getUsername());}
 public AppUser player(String token){if(token==null)throw GameException.unauthorized();return tokens.findByToken(token).map(TokenEntity::getUser).orElseThrow(GameException::unauthorized);}
 public Map<String,Object> intro(){return Map.of("briefing","Inspector Rao: Arjun Blackwood was murdered in his study at 9:40 PM during a dinner party at Blackwood Mansion. Search the mansion, examine evidence, and identify the killer.","suspects",CaseData.SUSPECTS,"rooms",CaseData.ROOMS);}
 @Transactional public GameStarted start(AppUser user){GameSession s=sessions.save(new GameSession(user));return new GameStarted(s.getId(),3,0);}
 private GameSession owned(String id,AppUser user){GameSession s=sessions.findById(id).orElseThrow(()->GameException.missing("Game session not found."));if(!s.getPlayer().getId().equals(user.getId()))throw GameException.unauthorized();if(!s.getStatus().equals("IN_PROGRESS"))throw GameException.bad("This game is no longer in progress.");return s;}
 private Set<Integer> ids(String sid){return collected.findBySession_IdOrderByClueId(sid).stream().map(CollectedClue::getClueId).collect(Collectors.toCollection(LinkedHashSet::new));}
 @Transactional public Object collect(String id,int clueId,AppUser user){GameSession s=owned(id,user);CaseData.Clue clue=CaseData.clue(clueId);if(clue==null)throw GameException.bad("Unknown clue id.");if(collected.existsBySession_IdAndClueId(id,clueId))throw GameException.bad("This clue has already been collected.");collected.save(new CollectedClue(s,clueId));s.progress();return Map.of("clue",clue,"collectedCount",ids(id).size());}
 public Object evidence(String id,AppUser user){GameSession s=owned(id,user);Set<Integer> set=ids(id);return Map.of("clues",set.stream().map(CaseData::clue).toList(),"clueCount",set.size(),"totalClues",6,"attemptsLeft",s.getAttemptsLeft(),"elapsedSeconds",s.elapsedSeconds(),"hintsUsed",s.getHintsUsed());}
 public Object talk(String id,String suspect,String question,AppUser user){GameSession s=owned(id,user);if(CaseData.SUSPECTS.stream().noneMatch(x->x.id().equals(suspect)))throw GameException.bad("Unknown suspect.");int q;try{q=Integer.parseInt(question);}catch(Exception e){throw GameException.bad("questionId must be 1, 2, or 3.");}if(q<1||q>3)throw GameException.bad("questionId must be 1, 2, or 3.");Set<Integer> clues=ids(id);String answer=CaseData.answer(suspect,question,clues.contains(5),clues.contains(6));return Map.of("suspectId",suspect,"answer",answer,"showEvidenceAvailable",!clues.isEmpty());}
 public Object confront(String id,String suspect,int clueId,AppUser user){owned(id,user);if(!ids(id).contains(clueId))throw GameException.bad("You must collect that clue before presenting it.");if(CaseData.clue(clueId)==null||CaseData.SUSPECTS.stream().noneMatch(x->x.id().equals(suspect)))throw GameException.bad("Unknown suspect or clue.");boolean exposed=suspect.equals("karan")&&List.of(2,3,4).contains(clueId);return Map.of("exposed",exposed,"reaction",exposed?"Karan grows nervous; his story begins to fall apart.":"The suspect studies the evidence but gives no revealing reaction.");}
 @Transactional public Object accuse(String id,AccuseRequest request,AppUser user){GameSession s=owned(id,user);Set<Integer> clues=ids(id);if(clues.size()<4)throw GameException.bad("Collect at least 4 clues before making an accusation.");if(request.proofClueIds().stream().anyMatch(x->!clues.contains(x)))throw GameException.bad("Both proof clues must already be collected.");boolean correct=request.suspectId().equals("karan")&&request.proofClueIds().stream().filter(List.of(2,3,4)::contains).distinct().count()>=2;if(correct){s.win();long elapsed=s.elapsedSeconds();LeaderboardEntry entry=scoring.entry(user.getUsername(),elapsed,s.getWrongAccusations(),s.getHintsUsed(),clues.size());leaderboard.save(entry);return Map.of("result","WIN","message","Inspector Rao: The evidence is decisive. Karan murdered Arjun Blackwood.","score",entry.getScore(),"rankTitle",entry.getRankTitle(),"elapsedSeconds",elapsed);}
 s.wrongGuess();return Map.of("result",s.getStatus().equals("GAME_OVER")?"GAME_OVER":"WRONG","message","Inspector Rao: That accusation is not supported by enough evidence. Reconsider the clues.","attemptsLeft",s.getAttemptsLeft());}
 @Transactional public Object hint(String id,AppUser user){GameSession s=owned(id,user);if(java.time.Duration.between(s.getLastProgressAt(),java.time.Instant.now()).getSeconds()<120)throw GameException.bad("A hint is available after 120 seconds without progress.");Set<Integer> clues=ids(id);CaseData.Clue next=CaseData.CLUES.stream().filter(c->!clues.contains(c.id())).findFirst().orElse(null);s.useHint();return Map.of("hint",next==null?"Review your evidence and speak with Inspector Rao.":"Inspector Rao suggests searching the "+next.room()+".","hintsUsed",s.getHintsUsed());}
 public Object top(){List<LeaderboardEntry> rows=leaderboard.findTop10ByOrderByScoreDescElapsedSecondsAsc();List<Map<String,Object>> out=new ArrayList<>();for(int i=0;i<rows.size();i++){LeaderboardEntry e=rows.get(i);out.add(Map.of("rank",i+1,"playerName",e.getPlayerName(),"score",e.getScore(),"rankTitle",e.getRankTitle(),"timeSeconds",e.getElapsedSeconds()));}return out;}
}
